import'package:flutter/material.dart';
class VisualNode{final String id;String label;Offset p;Map<String,dynamic>data;VisualNode(this.id,this.label,this.p,[Map<String,dynamic>?d]):data=d??{};}
class VisualLabsPage extends StatefulWidget{const VisualLabsPage({super.key});@override State<VisualLabsPage>createState()=>_VisualLabsPageState();}
class _VisualLabsPageState extends State<VisualLabsPage>{String type='Circuit';final nodes=<VisualNode>[VisualNode('a','A',const Offset(80,100),{'current':1}),VisualNode('g','Ground',const Offset(280,220))];void reset(String v){setState((){type=v;nodes..clear()..addAll(v=='Food web'?[VisualNode('grass','Grass',const Offset(70,220),{'population':100}),VisualNode('herb','Herbivore',const Offset(210,130),{'population':35}),VisualNode('pred','Predator',const Offset(340,60),{'population':8})]:v=='Pedigree'?[VisualNode('p1','Parent 1',const Offset(100,80),{'status':'carrier'}),VisualNode('p2','Parent 2',const Offset(300,80),{'status':'carrier'})]:v=='Free-body'?[VisualNode('body','Body',const Offset(200,150),{'mass':2,'fx':10,'fy':0})]:v=='Geo timeline'?[VisualNode('old','Older unit',const Offset(90,230),{'ageMa':250}),VisualNode('young','Younger unit',const Offset(280,80),{'ageMa':80})]:[VisualNode('a','A',const Offset(80,100),{'current':1}),VisualNode('g','Ground',const Offset(280,220))]);});}@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Visual Labs',style:Theme.of(context).textTheme.headlineMedium),DropdownButtonFormField(value:type,items:['Circuit','Food web','Pedigree','Free-body','Geo timeline'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>reset(v!)),const SizedBox(height:12),SizedBox(height:360,child:LayoutBuilder(builder:(c,b)=>Stack(children:[Positioned.fill(child:CustomPaint(painter:_GridPainter())),...nodes.map((n)=>Positioned(left:n.p.dx,top:n.p.dy,child:GestureDetector(onPanUpdate:(d)=>setState(()=>n.p=Offset((n.p.dx+d.delta.dx).clamp(0,b.maxWidth-90),(n.p.dy+d.delta.dy).clamp(0,b.maxHeight-60))),child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(children:[Text(n.label),Text(type,style:Theme.of(context).textTheme.labelSmall)])))))]))),const Text('Drag objects to construct the model. Flutter uses the same structured node/edge concept as the React Visual Labs; domain-specific solver adapters remain deterministic.')]);}}
class _GridPainter extends CustomPainter{@override void paint(Canvas c,Size s){final p=Paint()..color=Colors.blueGrey.withValues(alpha:.18)..strokeWidth=1;for(double x=0;x<s.width;x+=24)c.drawLine(Offset(x,0),Offset(x,s.height),p);for(double y=0;y<s.height;y+=24)c.drawLine(Offset(0,y),Offset(s.width,y),p);}@override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}